const input1Data = $('Format Results').first().json.result;
const input2Data = $('Potential Prices').first().json.data;

const lookupMap = new Map();
input2Data.forEach(item => {
    const key = `${item.symbol}_${item.calculated_for_date}`;
    lookupMap.set(key, item);
});

const result = input1Data.map(item1 => {
    const key = `${item1.symbol}_${item1.trade_date}`;
    const matchedData = lookupMap.get(key) || {};

    return {
        ...item1,
        ...matchedData
    };
});

return [{ json: { result } }];
